import { cookies } from "next/headers";
import { Metadata } from "next";
import Image from "next/image";
import "@styles/theme/main.global.css";
import "boxicons/css/boxicons.min.css";

export const metadata: Metadata = {
  title: "Woah AI",
  description: "Chat with you AI Partner with Privacy.",
};

type Theme = "dark" | "light";

export default async function Home() {
  const cookieStore = await cookies();
  const cookieTheme = cookieStore.get("theme")?.value;
  console.log("SSR Theme Cookie:", cookieTheme);
  const darkTheme = cookieTheme === "dark";

  return (
    <main
      className={`home-page ${
        darkTheme
          ? "bg-dark-black-primary text-dark-white-secondary"
          : "bg-light-white-primary text-light-black-secondary"
      } h-[100vh]`}
    >
      <div className="h-full flex items-center justify-center">
        <div className="w-[20%] h-auto">
          {/* For Historybar */}
          <div>hi</div>
          <div>history</div>
        </div>
        <div className="w-[80%] p-0.5 h-full flex items-center justify-center">
          <div className="flex flex-col h-[40%] min-h[380px] max-h-[1980px] gap-7 items-center">
            <div className="flex items-center justify-center">
              <span>
                <Image
                  src={`/logos/${darkTheme ? "logo-white" : "logo-black"}.png`}
                  alt="Woah AI"
                  width={60}
                  height={60}
                />
              </span>
            </div>
            <div className="">
              <div
                className={`flex flex-col justify-center gap-3.5 p-2 pb-1 rounded-[25px] w-[630px] min-h-[90px] max-h-[150px] ${
                  darkTheme
                    ? "bg-dark-black-secondary"
                    : "bg-light-white-secondary"
                }`}
              >
                <textarea
                  className={`text-left text-[15px] font-montserrat-sans pl-[5px] whitespace-pre-wrap break-words resize-none overflow-auto${
                    darkTheme
                      ? "text-dark-white-primary"
                      : "text-light-black-primary"
                  }`}
                  placeholder=" How Can We Help You?"
                ></textarea>
                <div className="">
                  <div className="flex items-center justify-between">
                    <div className="flex gap-3 items-center justify-start">
                      <span
                        className={`border border-solid border-gray-dark rounded-[90px] w-[80px] h-[35px] flex items-center justify-center cursor-pointer ${
                          darkTheme
                            ? "text-dark-white-primary"
                            : "text-light-black-primary"
                        }`}
                      >
                        Tools
                      </span>
                      <span
                        className={`border border-solid border-gray-dark rounded-full flex items-center justify-center cursor-pointer w-[35px] h-[35px] ${
                          darkTheme
                            ? "text-dark-white-primary"
                            : "text-light-black-primary"
                        }`}
                      >
                        <i
                          className="bx bx-plus"
                          style={{
                            color: darkTheme ? "#ffffff" : "#000000",
                            fontSize: "24px",
                          }}
                        ></i>
                      </span>
                    </div>
                    <div
                      className={`rounded-full flex items-center justify-center cursor-pointer w-[35px] h-[35px] ${
                        darkTheme
                          ? "bg-light-white-primary"
                          : "color-dark-black-primary"
                      }`}
                    >
                      <Image
                        src={`/icons/${
                          darkTheme ? "arrow-up-stroke-dark" : "arrow-up-stroke"
                        }.png`}
                        alt="Submit"
                        width={30}
                        height={30}
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div
              className={`flex justify-center items-center gap-4 ${
                darkTheme ? "text-white-primary" : "text-black-primary"
              }`}
            >
              <div
                className={`border border-solid border-gray-dark rounded-[90px] w-[125px] h-[35px] flex items-center justify-center cursor-pointer ${
                  darkTheme
                    ? "text-dark-white-primary"
                    : "text-light-black-primary"
                }`}
              >
                Create Image
              </div>
              <div
                className={`border border-solid border-gray-dark rounded-[90px] w-[125px] h-[35px] flex items-center justify-center cursor-pointer ${
                  darkTheme
                    ? "text-dark-white-primary"
                    : "text-light-black-primary"
                }`}
              >
                Edit Image
              </div>
              <div
                className={`border border-gray-dark border-solid rounded-[90px] w-[125px] h-[35px] flex items-center justify-center cursor-pointer ${
                  darkTheme
                    ? "text-dark-white-primary"
                    : "text-light-black-primary"
                }`}
              >
                Create Music
              </div>
              <div
                className={`border border-gray-dark border-solid rounded-[90px] w-[125px] h-[35px] flex items-center justify-center cursor-pointer ${
                  darkTheme
                    ? "text-dark-white-primary"
                    : "text-light-black-primary"
                }`}
              >
                Edit Music
              </div>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
